package practicecontrolflow;

public class Matrix {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		 int num=1;
         for( int i =1;i<=5;i++) {
        	
        	 for( int j=1;j<=5;j++) {
        		System.out.print(num+"\t");
        		num++;
        	 }System.out.println();
         }
	}

}
